mapper.delete:
 		delete cmr1010 where cr_acptno=#{CR_ACPTNO}
		   and cr_itemid=#{CR_ITEMID}
		   and cr_serno not in (select cr_serno from cmr1010
		                         where cr_acptno=#{CR_ACPTNO}
		                           and cr_itemid=#{CR_ITEMID}
		                           and rownum != 1)
